import{_ as o,l as n,o as e,c as s,v as i,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"Linux 提权路径","description":"","frontmatter":{"title":"Linux 提权路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linux-privesc.md","filePath":"cs/linux-privesc.md","lastUpdated":1789023840000}'),u={name:"cs/linux-privesc.md"};function h(_,a,x,E,m,b){const t=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="linux-提权路径" tabindex="-1">Linux 提权路径 <a class="header-anchor" href="#linux-提权路径" aria-label="Permalink to &quot;Linux 提权路径&quot;">​</a></h1><div class="epigraph"><p>从普通用户到特权，常见路是：SUID 程序缺陷、能力过宽、sudo 规则、可写的服务配置、内核漏洞。硬化是收这些面，而不是研究如何走完一条路。</p><footer>—— 据 Chen, Wagner 和 Dean 对 SUID 的讨论；Linux capabilities(7)；对照 Anderson</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/selinux-type-enforcement">SELinux</a>假定策略在。缺口是<strong>策略之外的提权面</strong>：文件模式、能力、sudo。本课列机制与硬化，不给提权利用步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>setuid 位让程序以文件属主身份跑，程序洞即属主权。capabilities 把 root 劈开，给错仍过大。缺口是盘点 SUID、收 sudo、不可写服务文件。</p><h3 id="内核" tabindex="-1">内核 <a class="header-anchor" href="#内核" aria-label="Permalink to &quot;内核&quot;">​</a></h3><p>内核洞是另一条，补丁管理课已强调窗口。本课不讨论利用。</p><p><span class="marginnote">capabilities(7)。禁止提权教程。Windows Kerberos 下一课换域身份。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单：找 SUID、查能力、只读配置、无交互 root sudo。对照容器后课的逃逸面同源。</p>',12)),(e(),l(c,null,{default:r(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E6%99%AE%E9%80%9A%E7%94%A8%E6%88%B7%22%5D%20--%3E%20SUID%5B%22SUID%20%E6%88%96%E8%BF%87%E5%AE%BD%E8%83%BD%E5%8A%9B%22%5D%0A%20%20USER%20--%3E%20SUDO%5B%22sudo%20%E8%A7%84%E5%88%99%22%5D%0A%20%20SUID%20--%3E%20HARD%5B%22%E7%9B%98%E7%82%B9%E5%B9%B6%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小特权在 Unix 上靠位与能力实现。域环境下一课用票据代替本地 root 叙事。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零利用。Windows Kerberos 攻击下一课讲协议失败模式与防御，不给操作步骤。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TE 之外，SUID/能力/sudo 仍是提权面。</li><li>硬化：盘点、收缩、只读配置。</li><li>内核窗口走补丁，不走利用课。</li><li>下一课 Kerberos 攻击面。</li><li>出处：Linux capabilities(7)；Anderson；Chen, Wagner and Dean。</li></ul>',8))])}const S=o(u,[["render",h]]);export{D as __pageData,S as default};
